#!/usr/bin/env node
// Mirror the canonical design tokens (design-tokens.json) to each platform.
//
// The three UI renderers (RN/React, iOS/SwiftUI, Android/Views) can't share code,
// but they CAN share colors. This generates a `@generated` color companion per
// platform from one source so the inspector looks identical everywhere and the
// palettes can't drift. Spacing/radii/type stay per-platform (tuned to each layout).
//
//   node scripts/sync-design-tokens.mjs           regenerate the 3 companion files
//   node scripts/sync-design-tokens.mjs --check    verify they're in sync (CI gate)

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const t = JSON.parse(readFileSync(join(repoRoot, 'design-tokens.json'), 'utf8'))

const banner = (line) =>
  `// @generated by scripts/sync-design-tokens.mjs from design-tokens.json — do not edit.\n${line}\n`

function emitTS() {
  const obj = (o) =>
    `{\n${Object.entries(o)
      .map(([k, v]) => `  ${k}: '#${v}',`)
      .join('\n')}\n}`
  return (
    banner('// Run `just sync-tokens` after editing design-tokens.json.') +
    `/* eslint-disable */
export const status = ${obj(t.status)} as const
export const method = ${obj(t.method)} as const
export const timing = ${obj(t.timing)} as const
export const paletteDark = ${obj(t.dark)} as const
export const paletteLight = ${obj(t.light)} as const
export const codeDark = ${obj(t.codeDark)} as const
export const codeLight = ${obj(t.codeLight)} as const
`
  )
}

// Colors live in design-tokens.json; geometry lives here, because a point on
// iOS, a dp on Android, a CSS pixel and an RN unit are the same size at 1x and
// there is no reason for four inspectors to disagree about how tall a chip is.
//
// The RN package keeps its own hand-written copy in styles/tokens.ts (it has
// extra steps the native surfaces have no use for); web reads the CSS block
// below. iOS and Android get generated files so their SwiftUI/Kotlin views can
// stop hardcoding numbers.
const metrics = {
  spacing: { xxs: 2, xs: 4, sm: 6, md: 8, ml: 10, lg: 12, ll: 14, xl: 16, xxl: 20, xxxl: 24 },
  // DESIGN.md's radius rule keys off `md` (6) for interactive controls.
  radius: { xs: 2, sm: 4, md: 6, lg: 10, xl: 14, pill: 999 },
  fontSize: { xxs: 9, xs: 10, sm: 12, md: 13, lg: 15, xl: 16, xxl: 18, display: 22, hero: 26 },
  // Every interactive control snaps to one of these. See DESIGN.md "One geometry".
  // `md` mirrors web's `--hakka-ctl-h-md` (28px) — the devtools-tight default
  // for buttons/inputs/selects/seg-buttons from the control-standardization pass.
  controlHeight: { badge: 18, chip: 24, icon: 28, md: 28, field: 36, nav: 40, bar: 44 },
  // The panel's left/right edge. Never a bare spacing step.
  layout: { gutter: 16, cardPadding: 12, sectionGap: 16, rowGap: 8 },
}

function emitSwift() {
  const lets = (prefix, o) =>
    Object.entries(o)
      .map(([k, v]) => `    static let ${prefix}${k[0].toUpperCase()}${k.slice(1)}: UInt32 = 0x${v}`)
      .join('\n')
  return (
    banner('// Run `just sync-tokens` after editing design-tokens.json.') +
    `import Foundation

/// Canonical Hakka color tokens (hex), shared with RN + Android.
enum HakkaTokens {
${lets('status', t.status)}
${lets('method', t.method)}
${lets('timing', t.timing)}
${lets('dark', t.dark)}
${lets('light', t.light)}
${lets('codeDark', t.codeDark)}
${lets('codeLight', t.codeLight)}
}

/// Canonical Hakka geometry, shared with RN + web + Android. Every interactive
/// control's height comes from ControlHeight; every page edge from
/// Layout.gutter. See DESIGN.md "One geometry".
///
/// public: the macOS app (a separate SPM module, HakkaApp) reaches for this
/// type directly — unlike HakkaTokens/Theme's colors, these are bare CGFloat
/// constants with no UIKit dependency, so there is no reason to fork a second
/// copy the way emitSwiftDesktop() has to for colors. See
/// apps/hakka/Sources/App/Helpers/Metrics.swift for the desktop's short
/// aliases onto this.
public enum HakkaMetrics {
${swiftGroup('spacing', metrics.spacing)}

${swiftGroup('radius', metrics.radius)}

${swiftGroup('fontSize', metrics.fontSize)}

${swiftGroup('controlHeight', metrics.controlHeight)}

${swiftGroup('layout', metrics.layout)}
}
`
  )
}

function swiftGroup(name, group) {
  const body = Object.entries(group)
    .map(([k, v]) => `        public static let ${k}: CGFloat = ${v}`)
    .join('\n')
  return `    public enum ${name[0].toUpperCase()}${name.slice(1)} {\n${body}\n    }`
}

function emitKotlin() {
  const consts = (prefix, o) =>
    Object.entries(o)
      .map(([k, v]) => `    const val ${prefix}${k[0].toUpperCase()}${k.slice(1)} = "#${v}"`)
      .join('\n')
  return (
    banner('// Run `just sync-tokens` after editing design-tokens.json.') +
    `package com.noodleapps.hakka.ui

/** Canonical Hakka color tokens (hex strings), shared with RN + iOS. */
internal object GeneratedTokens {
${consts('status', t.status)}
${consts('method', t.method)}
${consts('timing', t.timing)}
${consts('dark', t.dark)}
${consts('light', t.light)}
${consts('codeDark', t.codeDark)}
${consts('codeLight', t.codeLight)}
}

/**
 * Canonical Hakka geometry in dp/sp, shared with RN + web + iOS. Every
 * interactive control's height comes from [ControlHeight]; every page edge from
 * [Layout.gutter]. See DESIGN.md "One geometry".
 */
internal object GeneratedMetrics {
${kotlinGroup('Spacing', metrics.spacing)}

${kotlinGroup('Radius', metrics.radius)}

${kotlinGroup('FontSize', metrics.fontSize)}

${kotlinGroup('ControlHeight', metrics.controlHeight)}

${kotlinGroup('Layout', metrics.layout)}
}
`
  )
}

function kotlinGroup(name, group) {
  const body = Object.entries(group)
    .map(([k, v]) => `        const val ${k} = ${v}`)
    .join('\n')
  return `    object ${name} {\n${body}\n    }`
}

// The macOS app is the fifth UI surface. It cannot import the iOS UI module
// (UIKit-only), so it gets its own generated SwiftUI companion — data only,
// same rule as every platform: mappings live in hand-written code.
function emitSwiftDesktop() {
  const color = (hex) => {
    const r = parseInt(hex.slice(0, 2), 16) / 255
    const g = parseInt(hex.slice(2, 4), 16) / 255
    const b = parseInt(hex.slice(4, 6), 16) / 255
    return `Color(red: ${r.toFixed(4)}, green: ${g.toFixed(4)}, blue: ${b.toFixed(4)})`
  }
  const group = (name, o) => {
    const body = Object.entries(o)
      .map(([k, v]) => `        static let ${k} = ${color(v)}`)
      .join('\n')
    return `    enum ${name} {\n${body}\n    }`
  }
  return (
    banner('// Run `just sync-tokens` after editing design-tokens.json.') +
    `import SwiftUI

/// Canonical Hakka color tokens for the macOS app — same source as the four
/// inspector platforms. Data only; status/method/timing mappings live in Fmt.
enum ThemeTokens {
${group('Status', t.status)}

${group('Method', t.method)}

${group('Timing', t.timing)}

    // JSON syntax colors — codeDark only (this app has no adaptive
    // light/dark mirror yet, same call as Status/Method/Timing above).
${group('Code', t.codeDark)}
}
`
  )
}

function emitSwiftDemoPalette() {
  const color = (hex) => {
    const r = parseInt(hex.slice(0, 2), 16) / 255
    const g = parseInt(hex.slice(2, 4), 16) / 255
    const b = parseInt(hex.slice(4, 6), 16) / 255
    return `Color(red: ${r.toFixed(4)}, green: ${g.toFixed(4)}, blue: ${b.toFixed(4)})`
  }
  const body = Object.entries(t.dark)
    .map(([k, v]) => `    static let ${k} = ${color(v)}`)
    .join('\n')
  return (
    banner('// Run `just sync-tokens` after editing design-tokens.json.') +
    `import SwiftUI

/// The demo app's own chrome palette, generated from \`design-tokens.json\`'s
/// \`dark.*\` entries so it cannot drift from the SDK it demonstrates.
///
/// This is generated rather than referenced because \`HakkaTokens\`
/// (\`ios/Sources/UI/ThemeTokens.generated.swift\`) is \`internal\` to the HakkaUI
/// module and deliberately not public SDK surface. The Example app is a separate
/// module consuming HakkaUI/HakkaNetwork/HakkaCommon as plain SPM products, so it
/// cannot see those symbols. Generating from the same source keeps the values
/// honest without widening the SDK's public API, and \`just sync-tokens-check\`
/// fails CI if this file falls out of sync.
enum DemoPalette {
${body}
}
`
  )
}

function emitCSS() {
  const cssKey = (k) => (k === 'background' ? 'bg' : k.replace(/([a-z])([A-Z])/g, '$1-$2').toLowerCase())
  const vars = (group, o) =>
    Object.entries(o)
      .map(([k, v]) => `  --hakka-${group ? `${group}-` : ''}${cssKey(k)}: #${v};`)
      .join('\n')
  const layout = [
    // Rounding on a rail or bar, where a visible corner reads as a gap.
    ...Object.entries(metrics.radius).map(([k, v]) => [`radius-${k}`, `${v}px`]),
    ['radius-circle', '50%'],
    // Hugs a glyph to its label tighter than `space-xs` — pill interiors only.
    ...Object.entries(metrics.spacing).map(([k, v]) => [`space-${k}`, `${v}px`]),
    // The panel's left/right edge. Every top-level row, section title and list
    // row aligns here — never a bare `space-*` step, so no component can pick
    // its own page edge.
    ['gutter', '16px'],
    ['font-xxs', '9px'],
    ['font-xs', '10px'],
    // Mono DATA columns (duration/size/status/waterfall) and textarea value
    // fields — one size up from font-xs so digits don't read as fine print;
    // chips/labels stay font-xs. See web-control-standardization-2026-08.md
    // "Typography".
    ['font-data', '11px'],
    ['font-sm', '12px'],
    ['font-md', '13px'],
    ['font-lg', '15px'],
    ['font-xl', '18px'],
    // Android/Linux have no SF Mono/Cascadia Mono — Roboto Mono/Droid Sans Mono
    // close that gap so the mono stack never falls through to the generic
    // (proportional-metric) 'monospace' keyword there.
    [
      'font-mono',
      "ui-monospace, 'SF Mono', 'Cascadia Mono', 'Roboto Mono', 'Droid Sans Mono', Menlo, Monaco, monospace",
    ],
    // Sans stack as a token, not a raw literal — keeps styles.ts from
    // re-drifting into separate copies.
    ['font-sans', 'system-ui, -apple-system, sans-serif'],
    // One control-height scale: every small interactive control is ctl-h;
    // bars/action rows are ctl-h-lg; 44px stays the row/tab tap-target
    // constant. No component invents its own height.
    ['ctl-h-xs', '18px'],
    ['ctl-h-sm', '20px'],
    // Devtools-tight default: buttons (incl. primary), inputs, selects,
    // seg-buttons. See web-control-standardization-2026-08.md "Target system".
    // Derived from metrics.controlHeight (md/field/bar) so it can't drift
    // from the Swift/Kotlin/RN copy the way a hand-typed literal could.
    ['ctl-h-md', `${metrics.controlHeight.md}px`],
    ['ctl-h', '26px'],
    ['ctl-h-lg', '32px'],
    ['ctl-h-xl', `${metrics.controlHeight.field}px`],
    ['ctl-h-tap', `${metrics.controlHeight.bar}px`],
    // Default panel height on a mobile-width floating panel (< 680px) — a
    // fixed 60% fraction, not the browser's own concept of "medium," chosen
    // to match iOS's custom UISheetPresentationController detent and
    // Android's HakkaBottomSheet mediumHeight (both 60%, deliberately not
    // UIKit's system .medium() at ~50%). See MOBILE-LAYOUT-SPEC.md §0/§2:
    // partial is the resting state, full-screen is an explicit escalation.
    ['panel-height-mobile', '60dvh'],
    // Named tint strengths for the color-mix() pattern — three intents, not
    // one-off percentages.
    ['tint-hover', '9%'],
    ['tint-active', '15%'],
    ['tint-border', '40%'],
  ]
    .map(([k, v]) => `  --hakka-${k}: ${v};`)
    .join('\n')
  return `/* @generated by scripts/sync-design-tokens.mjs from design-tokens.json — do not edit. */
/* Run \`just sync-tokens\` after editing design-tokens.json. */
/* Canonical Hakka look = iOS navy dark (default). Set theme="light" on the
   <hakka-inspector> element for the light palette. Spacing/radii/type are the web
   layout scale — intentionally per-platform, not unified in design-tokens.json. */
:host {
${vars('status', t.status)}
${vars('method', t.method)}
${vars('timing', t.timing)}
${vars('', t.dark)}
${vars('code', t.codeDark)}
  color-scheme: dark;
${layout}
}

:host([theme='light']) {
${vars('', t.light)}
${vars('code', t.codeLight)}
  color-scheme: light;
}
`
}

const targets = [
  ['packages/hakka-react-native/src/ui/styles/tokens.generated.ts', emitTS()],
  ['ios/Sources/UI/ThemeTokens.generated.swift', emitSwift()],
  ['android/hakka-ui/src/main/kotlin/com/noodleapps/hakka/ui/GeneratedTokens.kt', emitKotlin()],
  ['packages/hakka-browser/src/ui/tokens.css', emitCSS()],
  ['apps/hakka/Sources/App/Shared/ThemeTokens.generated.swift', emitSwiftDesktop()],
  ['ios/Example/Sources/DemoPalette.generated.swift', emitSwiftDemoPalette()],
]

const check = process.argv.includes('--check')
const drift = []
for (const [rel, content] of targets) {
  const path = join(repoRoot, rel)
  const actual = existsSync(path) ? readFileSync(path, 'utf8') : null
  if (actual === content) continue
  if (check) {
    drift.push(rel)
  } else {
    mkdirSync(dirname(path), { recursive: true })
    writeFileSync(path, content)
    console.log(`  wrote ${rel}`)
  }
}

if (check) {
  if (drift.length) {
    console.error(`Design tokens out of sync (${drift.length}):`)
    for (const f of drift) console.error(`  ${f}`)
    console.error('\nFix: run `just sync-tokens` (edit design-tokens.json, never the generated files).')
    process.exit(1)
  }
  console.log(`Design tokens in sync (${targets.length} platforms).`)
} else {
  console.log(`Done. Mirrored design-tokens.json → ${targets.length} platforms.`)
}
